    ("argocd-gitops-model", "GitOps Desired State & Reconciliation Loop", "gitops", "basic", "Git stores desired manifests; Argo CD compares rendered desired state with live cluster state and reports or reconciles the difference.", "Git revision → render manifests → compare live state → sync → health assessment"),
    ("argocd-install", "Argo CD Components & Installation", "gitops", "basic", "Argo CD includes API/UI, repo server, application controller, Redis and repository integrations. Secure the control plane and size it for app count, manifest render cost and cluster fleet.", "Install pinned chart/manifests; expose UI only through authenticated ingress"),
    ("argocd-application", "Application CRD: Source, Destination & Project", "gitops", "basic", "An Application defines source repository/path/revision, destination cluster/namespace and AppProject. Review all three boundaries before granting sync rights.", "repoURL + path + targetRevision → server/namespace"),
    ("argocd-source-types", "Git, Helm & OCI Application Sources", "gitops", "intermediate", "Argo CD can render plain manifests, Kustomize, Helm and supported plugins from configured sources. Pin immutable revisions and ensure repo-server has only necessary credentials.", "Use chart version plus values files in a Helm source"),
    ("argocd-helm-values", "Helm Values Files & Parameters in Argo CD", "gitops", "intermediate", "Applications can layer Helm values files and parameters, with precedence that can change effective manifests. Keep environment values in Git and avoid hidden UI-only overrides.", "valueFiles: [values.yaml, values-prod.yaml]"),
